#!/usr/bin/env node
/**
 * Phase 4b: Generate shadow-cljs.edn with per-demo modules.
 *
 * Run from repo root: node compiler/gen-shadow-config.js
 *
 * This reads demos/demo-modules.json (generated by rewrite-demos.js)
 * and produces compiler/shadow-cljs.edn with one :module per demo.
 */

import { writeFileSync, readFileSync } from 'fs';
import { join } from 'path';

const repoRoot = process.cwd();
const modulesPath = join(repoRoot, 'compiler', 'demo-modules.json');

let modules = {};
try {
  modules = JSON.parse(readFileSync(modulesPath, 'utf-8'));
} catch (e) {
  console.error('No demo-modules.json found. Run rewrite-demos.js first.');
  process.exit(1);
}

// Build the :modules map as EDN
// Module keys and output filenames
// Clojure keywords allow hyphens, and shadow-cljs uses the keyword name
// as the output filename. So :rm-hull-5736733 produces rm-hull-5736733.js
const moduleEntries = Object.entries(modules)
  .map(([slug, cfg], idx) => {
    const modKey = slug; // uses hyphens, which are valid in CLJS keywords
    const nsName = cfg.entries[0]; // e.g. demo.mjg123-1098417
    // All demo modules depend on the shared enchilada.core module
    // (so :main is the default, demo modules share the common chunk)
    return `    :${modKey} {:entries [${nsName}] :depends-on #{:main}}`;
  })
  .join('\n');

const ednContent = `{:deps true
  :npm-deps true

  :builds
  {
    ;; Phase 4: per-demo modules compiled from fetched gists
    ;; The :main module (enchilada.core) serves as the shared default
    ;; Namespace rewritten to demo.<slug> by compiler/rewrite-demos.js
    :demos {:target :browser
            :output-dir "public/js"
            :asset-path "/js"
            :modules {
      :main {:entries [enchilada.core]}
${moduleEntries}
            }
            ;; Foreign libs are no longer needed - jQuery and React are loaded via CDN in base.njk
            ;; The :foreign-libs are commented out because loading them via shadow-cljs
            ;; can cause conflicts with the global jQuery/React we load in the page.
    }

    ;; Phase 3 test module
    :macros-test {:target :browser
                  :output-dir "public/js"
                  :asset-path "/js"
                  :modules {:macros-main {:entries [enchilada.util.macros-test]}}}
  }
}
`;

writeFileSync(join(repoRoot, 'compiler', 'shadow-cljs.edn'), ednContent);
console.log(`Generated shadow-cljs.edn with ${Object.keys(modules).length} demo modules`);
